INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN('accounts.view','accounts.manage','journal_entries.view','journal_entries.create','journal_entries.edit','journal_entries.post','accounting_periods.view','accounting_periods.manage','accounting_setup.view','accounting_setup.manage','trial_balance.view','employees.view','employees.manage','employee_custodies.view','employee_custodies.create','employee_custodies.edit','employee_custodies.issue','employee_custodies.settle','employee_custodies.cancel') WHERE r.code='super_admin' ON DUPLICATE KEY UPDATE role_id=VALUES(role_id);
